CREATE TABLE IF NOT EXISTS tax_rates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,country_code CHAR(2) NULL,rate DECIMAL(8,4) NOT NULL DEFAULT 0,inclusive TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY tax_country(country_code,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,invoice_number VARCHAR(80) NOT NULL,subtotal DECIMAL(14,2) NOT NULL DEFAULT 0,tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0,shipping_amount DECIMAL(14,2) NOT NULL DEFAULT 0,discount_amount DECIMAL(14,2) NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'USD',billing_address TEXT NULL,shipping_address TEXT NULL,payment_method VARCHAR(80) NULL,qr_payload TEXT NULL,issued_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY invoice_number_unique(invoice_number),UNIQUE KEY invoice_order(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoice_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NULL,title VARCHAR(500) NOT NULL,sku VARCHAR(190) NULL,quantity DECIMAL(12,3) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY invoice_items_invoice(invoice_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS credit_notes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,credit_note_number VARCHAR(80) NOT NULL,amount DECIMAL(14,2) NOT NULL,reason VARCHAR(500) NULL,status ENUM('issued','cancelled') NOT NULL DEFAULT 'issued',issued_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY credit_note_number_unique(credit_note_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
